interface Policy {
    maxRequests: number;
    windowMs: number;
}

function createRateLimiter(nowMs?: () => number): RateLimiter {
    const policy: Policy = { maxRequests: 3, windowMs: 1000 };
    const timestampQueueMap = new Map<string, Array<number>>();
    const now = nowMs || (() => Date.now());

    function trackRequest(key: string) {
        let queue = timestampQueueMap.get(key);
        if (!queue) {
            queue = [];
            timestampQueueMap.set(key, queue);
        }
        queue.push(now());
    }

    function reset(key: string) {
        timestampQueueMap.delete(key);
    }

    return {
        trackRequest,
        reset
    };
}

export { createRateLimiter };
