export function createRateLimiter(): RateLimiter {
  const windows: Map<string, { count: number; lastReset: number }> = new Map();

  return {
    allow(key, nowMs) {
      this.resetIfNeeded(key, nowMs);
      const currentWindow = windows.get(key);
      if (currentWindow?.count < limit) {
        currentWindow.count++;
        return true;
      }
      return false;
    },
    remaining(key, nowMs) {
      this.resetIfNeeded(key, nowMs);
      const currentWindow = windows.get(key);
      return Math.max(0, limit - currentWindow?.count ?? 0);
    },
    reset(key) {
      windows.delete(key);
    }
  };
}

const limit = 3;
const windowMs = 1000;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
