import { Map } from "immutable";

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs = 1000
  ): void {
    const expiresAt = nowMs + ttlMs;
    cache.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    return has(key, nowMs) ? cache.get(key)!.value : undefined;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    return Boolean(entry && entry.expiresAt > nowMs);
  }

  function delete(key: string): boolean {
    if (cache.has(key)) {
      cache.delete(key);
      return true;
    }
    return false;
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [_, entry] of cache.entries()) {
      if (entry.expiresAt > nowMs) {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  return { set, get, has, delete, size, clear };
}
