export function createRateLimiter() {
  const state: Record<string, { count: number; windowStart: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const window = state[key] ?? { count: 0, windowStart: nowMs };
      const elapsed = nowMs - window.windowStart;

      if (elapsed >= 1000) {
        window.count = 1;
        window.windowStart = nowMs;
      } else {
        window.count += 1;
      }

      state[key] = window;
      return window.count <= 3;
    },

    reset(key: string): void {
      delete state[key];
    },
  };
}
