```typescript
export function createEventEmitter(): EventEmitter {
  const events: Record<string, Listener[]> = {};

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push(listener);
      return events[event].length;
    },
    once(event: string, listener: Listener): number {
      const onceListener = (...args: unknown[]): unknown[] => {
        const result = listener(...args);
        this.off(event, onceListener);
        return result;
      };

      return this.on(event, onceListener);
    },
    off(event: string, listener: Listener): boolean {
      if (!events[event]) {
        return false;
      }

      events[event] = events[event].filter(l => l !== listener);

      return events[event].length > 0;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = events[event] || [];
      const results: unknown[] = [];

      for (const listener of listeners) {
        results.push(listener(payload));
      }

      return results;
    },
    listenerCount(event: string): number {
      return events[event]?.length ?? 0;
    }
  };
}
