export function createRateLimiter(nowMs: () => number): { allow: (key: string) => boolean; reset: (key: string) => void } {
    const windows = new Map<string, number[]>();

    return {
        allow(key: string): boolean {
            const currentTime = nowMs();
            let windowKey = `${key}-${Math.floor(currentTime / 1000)}`;
            if (!windows.has(windowKey)) {
                windows.set(windowKey, [currentTime]);
            } else {
                while (windows.get(windowKey)[0] < currentTime - 1000) {
                    windows.get(windowKey).shift();
                }
                if (windows.get(windowKey).length >= 3) {
                    return false;
                }
                windows.get(windowKey).push(currentTime);
            }
            return true;
        },
        reset(key: string): void {
            const currentTime = nowMs();
            let windowKey = `${key}-${Math.floor(currentTime / 1000)}`;
            if (windows.has(windowKey)) {
                windows.delete(windowKey);
            }
        }
    };
}
