export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const windows: Map<string, number[]> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      let windowStart = Math.floor(nowMs / windowMs) * windowMs;

      if (nowMs - windowStart >= windowMs) {
        windows.set(key, []);
      }

      const currentWindow = windows.get(key);
      if (!currentWindow || currentWindow.length === 0) {
        currentWindow.push(nowMs);
        return true;
      }

      const lastAccessTime = currentWindow[currentWindow.length - 1];
      if (nowMs - lastAccessTime < windowMs / limit) {
        return false;
      } else {
        currentWindow.push(nowMs);
        return true;
      }
    },

    remaining(key: string, nowMs: number): number {
      let windowStart = Math.floor(nowMs / windowMs) * windowMs;

      if (nowMs - windowStart >= windowMs) {
        windows.set(key, []);
      }

      const currentWindow = windows.get(key);
      if (!currentWindow) return limit;

      const lastAccessTime = currentWindow[currentWindow.length - 1];
      const remainingCalls = Math.max(limit - ((nowMs - lastAccessTime) / (windowMs / limit)), 0);
      return remainingCalls;
    },

    reset(key: string): void {
      windows.delete(key);
    }
  };
}
