export function createTodoApp(): {
    addTodo: (text: string) => { id: number; text: string; completed: boolean };
    getTodo: (id: number) => { id: number; text: string; completed: boolean } | undefined;
    toggleTodo: (id: number) => void;
    deleteTodo: (id: number) => boolean;
    listTodos: () => Array<{ id: number; text: string; completed: boolean }>;
    listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
    listPending: () => Array<{ id: number; text: string; completed: boolean }>;
    clearCompleted: () => void;
} {
    const todos: { [id: number]: { id: number; text: string; completed: boolean } } = {};
    let nextId = 1;

    function addTodo(text: string): { id: number; text: string; completed: boolean } {
        const todo = { id: nextId++, text, completed: false };
        todos[todo.id] = todo;
        return todo;
    }

    function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
        return todos[id];
    }

    function toggleTodo(id: number): void {
        if (todos[id]) {
            todos[id].completed = !todos[id].completed;
        }
    }

    function deleteTodo(id: number): boolean {
        if (todos[id]) {
            delete todos[id];
            return true;
        }
        return false;
    }

    function listTodos(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos);
    }

    function listCompleted(): Array<{ id: number; text: string; completed: boolean }>;
    function listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos).filter(todo => todo.completed);
    }

    function listPending(): Array<{ id: number; text: string; completed: boolean }>;
    function listPending(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos).filter(todo => !todo.completed);
    }

    function clearCompleted(): void {
        const keys = Object.keys(todos).map(Number);
        for (const key of keys) {
            if (todos[key] && todos[key].completed) {
                delete todos[key];
            }
        }
    }

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted
    };
}
