export function createTtlCache(): TtlCache {
  const cache: Record<string, { value: unknown; expiresAt: number }> = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
      if (ttlMs === 0) {
        cache[key] = { value, expiresAt: nowMs };
      } else {
        const expiresAt = nowMs + ttlMs;
        cache[key] = { value, expiresAt };
      }
    },
    get(key: string, nowMs: number): unknown {
      if (!cache.hasOwnProperty(key)) return undefined;

      const item = cache[key];
      if (nowMs >= item.expiresAt) {
        delete cache[key];
        return undefined;
      }

      return item.value;
    },
    has(key: string, nowMs: number): boolean {
      const value = this.get(key, nowMs);
      return value !== undefined;
    },
    delete(key: string): boolean {
      if (cache.hasOwnProperty(key)) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const key in cache) {
        if (nowMs < cache[key].expiresAt && cache.hasOwnProperty(key)) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      cache = {};
    }
  };
}
