export function createEventEmitter<TArgs extends any[], TReturn = void>() {
    const listeners: Map<string, Array<(args: TArgs) => TReturn>> = new Map();

    const emit = (eventName: string, ...args: TArgs): TReturn[] => {
        const eventListeners = listeners.get(eventName) || [];
        const results: TReturn[] = [];
        for (const listener of eventListeners) {
            results.push(listener(...args));
        }
        return results;
    };

    const on = (eventName: string, listener: (args: TArgs) => TReturn): void => {
        listeners.get(eventName)?.push(listener) ?? listeners.set(eventName, [listener]);
    };

    const once = (eventName: string, listener: (args: TArgs) => TReturn): void => {
        const listenerWrapper = (args: TArgs): TReturn => {
            const result = listener(args);
            listeners.delete(eventName);
            return result;
        };
        listeners.get(eventName)?.push(listenerWrapper) ?? listeners.set(eventName, [listenerWrapper]);
    };

    const off = (eventName: string, listener: (args: TArgs) => TReturn): void => {
        const eventListeners = listeners.get(eventName) || [];
        const filteredListeners = eventListeners.filter(l => !l === listener);
        listeners.set(eventName, filteredListeners);
    };

    return { emit, on, once, off };
}
