```typescript
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  listeners: Record<string, Listener[]>;
  onceListeners: Record<string, Listener[]>;
}

function createEventEmitter(): EventEmitter {
  const emitter: EventEmitter = {
    listeners: {},
    onceListeners: {},
  };

  function on(event: string, listener: Listener): number {
    if (!emitter.listeners[event]) {
      emitter.listeners[event] = [];
    }
    emitter.listeners[event].push(listener);
    return emitter.listenerCount(event);
  }

  function once(event: string, listener: Listener): number {
    if (!emitter.onceListeners[event]) {
      emitter.onceListeners[event] = [];
    }
    emitter.onceListeners[event].push(listener);
    return emitter.listenerCount(event);
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = emitter.listeners[event] || [];
    const onceListeners = emitter.onceListeners[event] || [];
    const listenerIndex = listeners.findIndex(l => l === listener);
    const onceListenerIndex = onceListeners.findIndex(l => l === listener);

    const removed = listenerIndex !== -1 || onceListenerIndex !== -1;
    if (removed) {
      if (listenerIndex !== -1) {
        listeners.splice(listenerIndex, 1);
      }
      if (onceListenerIndex !== -1) {
        onceListeners.splice(onceListenerIndex, 1);
      }
    }
    return removed;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const listeners = emitter.listeners[event] || [];
    const onceListeners = emitter.onceListeners[event] || [];
    const results: unknown[] = [];

    for (const listener of listeners) {
      const result = listener(payload);
      results.push(result);
    }

    for (const listener of onceListeners) {
      const result = listener(payload);
      results.push(result);
      const listenerIndex = emitter.onceListeners[event].findIndex(l => l === listener);
      if (listenerIndex !== -1) {
        emitter.onceListeners[event].splice(listenerIndex, 1);
      }
    }

    return results;
  }

  function listenerCount(event: string): number {
    return (emitter.listeners[event] || []).length + (emitter.onceListeners[event] || []).length;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}
