export function createRateLimiter(): RateLimiter {
  const state: Record<string, { windowStart: number; count: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const windowStart = Math.max(state[key]?.windowStart || 0, nowMs - 1000);
      const windowEnd = windowStart + 1000;
      const currentCount = state[key]?.count || 0;

      if (nowMs - windowStart >= 1000) {
        state[key] = { windowStart, count: 0 };
      }

      if (currentCount < 3) {
        state[key] = { ...state[key], count: currentCount + 1 };
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const windowStart = Math.max(state[key]?.windowStart || 0, nowMs - 1000);
      const currentCount = state[key]?.count || 0;
      return Math.max(0, 3 - currentCount);
    },
    reset(key: string): void {
      delete state[key];
    }
  };
}
