export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache: Record<string, { value: unknown; expiresAt: number }> = {};
  const defaultTTL = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const ttl = ttlMs ?? defaultTTL;
      cache[key] = { value, expiresAt: nowMs + ttl };
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (!entry || nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      return entry && nowMs < entry.expiresAt;
    },
    delete(key: string): boolean {
      const wasPresent = key in cache;
      delete cache[key];
      return wasPresent;
    },
    size(nowMs: number): number {
      return Object.values(cache).filter((entry) => nowMs < entry.expiresAt).length;
    },
    clear() {
      cache = {};
    },
  };
}
