interface Listener<T> {
    (): T;
}

export function createEventEmitter<EventName extends string, Listeners = ((...args: any[]) => any)[]>(
    eventNames?: EventName[]
): { emit: (event: EventName, ...args: any[]) => Promise<ReturnValues> };
{
    if (typeof eventNames !== 'function' && !Array.isArray(eventNames)) {
        throw new TypeError('Event names must be a function or array.');
    }

    const listeners = {};

    return {
        emit: async (...args): Promise<ReturnValues> => {
            const event: EventName | string = args[0];
            let returnValues: ReturnValues = [];

            if (typeof eventNames === 'function') {
                eventNames = eventNames();
            } else {
                if (!Array.isArray(eventNames)) {
                    throw new TypeError('Event names must be a function or array.');
                }
            }

            for (const listenerName of eventNames) {
                const listener = listeners[listenerName];

                if (listener === undefined) {
                    continue;
                }

                returnValues.push(await listener(...args));
            }

            return returnValues;
        },
        off: (event?: EventName, listener: Listener<undefined> | undefined): void => {
            let eventNamesToRemove: EventName[] | undefined;

            if (typeof event === 'function') {
                event = event();
            } else if (Array.isArray(event)) {
                eventNamesToRemove = [...event];
            }

            if (event === undefined) {
                delete listeners;
                return;
            }

            const listenerNamesToUnregister: ListenerName[] = [];

            for (const name of Object.keys(listeners)) {
                if ((listeners[name] as Listener<undefined>) === listener) {
                    listenerNamesToUnregister.push(name);
                }
            }

            if (eventNamesToRemove !== undefined) {
                eventNamesToRemove.forEach((name: EventName) => {
                    if (listenerNamesToUnregister.includes(name)) {
                        listenerNamesToUnregister.splice(listenerNamesToUnregister.indexOf(name), 1);
                    } else {
                        delete listeners[name];
                    }
                });
            }

            for (const name of listenerNamesToUnregister) {
                delete listeners[name];
            }
        },
    };
}

export type ReturnValues = (...args: any[]) => Promise<any>;
