export function createEventEmitter(): {
  on(event: string, listener: (payload: unknown) => unknown): number;
  once(event: string, listener: (payload: unknown) => unknown): number;
  off(event: string, listener: (payload: unknown) => unknown): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
} {
  const listeners: { [key: string]: ((payload: unknown) => unknown)[] } = {};
  return {
    on(event: string, listener: (payload: unknown) => unknown): number {
      if (!listeners[event]) listeners[event] = [];
      const count = listeners[event].length;
      listeners[event].push(listener);
      return count;
    },
    once(event: string, listener: (payload: unknown) => unknown): number {
      let count = this.on(event, listener);
      listener();
      this.off(event, listener);
      return count;
    },
    off(event: string, listener: (payload: unknown) => unknown): boolean {
      if (!listeners[event]) return false;
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) return [];
      const result = new Array(listeners[event].length);
      for (let i = 0; i < listeners[event].length; i++) {
        result[i] = listeners[event][i](payload);
      }
      return result;
    },
    listenerCount(event: string): number {
      return listeners[event] ? listeners[event].length : 0;
    },
  };
}
