export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = rateLimiters.get(key);
      if (!keyState) return false;

      const { windowStart, quota } = keyState;
      if (nowMs - windowStart >= windowMs) {
        rateLimiters.set(key, { windowStart: nowMs, quota: limit });
      }

      const remaining = quota - 1;
      if (remaining < 0) return false;

      rateLimiters.set(key, { windowStart: nowMs, quota: remaining });
      return true;
    },

    remaining(key: string, nowMs: number): number {
      const keyState = rateLimiters.get(key);
      if (!keyState) return -1;

      const { windowStart, quota } = keyState;
      if (nowMs - windowStart >= windowMs) {
        return quota;
      }

      return quota - 1;
    },

    reset(key: string): void {
      rateLimiters.set(key, { windowStart: 0, quota: limit });
    }
  };
}

const rateLimiters = new Map<string, any>();

export type RateLimiter = {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
};
