export function createTtlCache(): TtlCache {
  const cache: { [key: string]: number } = {};
  let expiresAt = Date.now() + 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      if (ttlMs !== undefined && ttlMs < 0) {
        throw new Error('Negative TTL is invalid');
      }

      const existingTtl = cache[key];
      if (existingTtl !== undefined && (nowMs >= expiresAt || (expiresAt - nowMs) <= ttlMs)) {
        delete cache[key];
      }
      cache[key] = nowMs + (ttlMs === undefined ? 1000 : ttlMs);
      expiresAt = Math.min(expiresAt, nowMs + ttlMs || 1000);
    },

    get(key: string, nowMs: number): unknown {
      const value = cache[key];
      if (value !== undefined && (nowMs >= expiresAt)) {
        delete cache[key];
      }
      return value;
    },

    has(key: string, nowMs: number) {
      return cache[key] !== undefined;
    },

    delete(key: string): boolean {
      const existing = cache[key];
      if (existing === undefined) {
        return false;
      }
      delete cache[key];
      return true;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const key in cache) {
        const value = cache[key];
        if (value !== undefined && nowMs < value) {
          count++;
        }
      }
      return count;
    },

    clear() {
      cache = {};
      expiresAt = Date.now() + 1000;
    },
  };
}
