interface Listener {
  callback: (data: any) => any;
  once: boolean;
  called: boolean;
}

export const createEventEmitter = (): EventEmitter => {
  const emitter: EventEmitter = {
    register(event: string, callback: (data: any) => any, once?: boolean): void => {
      if (!emitter[event]) {
        emitter[event] = [];
      }
      const listener: Listener = {
        callback,
        once,
        called: false,
      };
      emitter[event].push(listener);
    },
    remove(event: string, callback: (data: any) => any, once?: boolean): void => {
      if (!emitter[event]) return;
      const listeners = emitter[event];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        if (listener.callback === callback && (listener.once === once)) {
          listeners.splice(i, 1);
          return;
        }
      }
    },
    emit(event: string, data: any): any[] {
      const results: any[] = [];
      if (!emitter[event]) return results;
      for (const listener of emitter[event]) {
        if (listener.once && !listener.called) {
          results.push(listener.callback(data));
          listener.called = true;
        } else {
          results.push(listener.callback(data));
          listener.called = true;
        }
      }
      return results;
    },
  };
  return emitter;
};

