export function createEventEmitter(): EventEmitter {
  const eventListeners: Map<string, Listener[]> = new Map();
  const onceListeners: Map<string, Listener[]> = new Map();
  return {
    on(event: string, listener: Listener): number {
      const listeners = eventListeners.get(event) || [];
      listeners.push(listener);
      eventListeners.set(event, listeners);
      return listeners.length;
    },
    once(event: string, listener: Listener): number {
      const listeners = onceListeners.get(event) || [];
      listeners.push(listener);
      onceListeners.set(event, listeners);
      return listeners.length;
    },
    off(event: string, listener: Listener): boolean {
      const listeners = eventListeners.get(event);
      if (!listeners) return false;
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
        eventListeners.set(event, listeners);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = eventListeners.get(event);
      if (!listeners) return [];
      const onceListenersForEvent = onceListeners.get(event);
      const results: unknown[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        if (listener instanceof Function) {
          results.push(listener(payload));
          if (onceListenersForEvent && onceListenersForEvent.includes(listener)) {
            onceListenersForEvent = onceListenersForEvent.filter(l => l !== listener);
            listeners.splice(i, 1);
            i--; // adjust index since we removed an element
          }
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return eventListeners.get(event) ? eventListeners.get(event).length : 0;
    }
  };
}
