export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache: Record<string, { value: unknown, expiresAt: number }> = {};

  function calculateExpiresAt(nowMs: number, ttlMs: number | undefined): number {
    if (ttlMs === undefined) {
      return nowMs + 1000;
    }
    return nowMs + ttlMs;
  }

  return {
    set(key, value, nowMs, ttlMs = undefined) {
      if (cache[key]) {
        cache[key].value = value;
        cache[key].expiresAt = calculateExpiresAt(nowMs, ttlMs);
      } else {
        cache[key] = { value, expiresAt: calculateExpiresAt(nowMs, ttlMs) };
      }
    },

    get(key, nowMs) {
      if (cache[key]) {
        const expiresAt = cache[key].expiresAt;
        if (nowMs >= expiresAt) {
          return cache[key].value;
        }
      }
      return undefined;
    },

    has(key, nowMs) {
      return cache[key] !== undefined;
    },

    delete(key) {
      if (cache[key]) {
        delete cache[key];
        return true;
      }
      return false;
    },

    size(nowMs) {
      let count = 0;
      for (const [key, entry] of Object.entries(cache)) {
        const expiresAt = entry.expiresAt;
        if (expiresAt < nowMs) {
          count++;
        }
      }
      return count;
    },

    clear() {
      cache = {};
    }
  };
}
