export function createTtlCache(): TtlCache {
  const entries = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (entries.has(key)) {
        const existing = entries.get(key)!;
        entries.delete(key);
      }
      const expiresAt = nowMs + (ttlMs || 1000);
      entries.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      if (entries.has(key)) {
        const entry = entries.get(key)!;
        if (entry.expiresAt > nowMs) {
          return entry.value;
        }
        entries.delete(key);
        return undefined;
      }
      return undefined;
    },
    has(key: string, nowMs: number): boolean {
      if (entries.has(key)) {
        const entry = entries.get(key)!;
        if (entry.expiresAt > nowMs) {
          return true;
        }
        entries.delete(key);
        return false;
      }
      return false;
    },
    delete(key: string): boolean {
      if (entries.has(key)) {
        entries.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, { expiresAt }] of entries.entries()) {
        if (expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      entries.clear();
    }
  };
