export function createRateLimiter(): RateLimiter {
  const windowMs = 1000;
  const limit = 3;
  const state = new Map<string, { remaining: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = state.get(key);
      if (!entry) {
        entry = { remaining: limit, windowStart: nowMs };
        state.set(key, entry);
      }

      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.remaining = limit;
      }

      if (entry.remaining > 0) {
        entry.remaining--;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = state.get(key);
      if (!entry) {
        return limit;
      }

      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.remaining = limit;
      }

      return entry.remaining;
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
