  return {
    allow: (key: string, nowMs: number): boolean => {
      const entry = state.get(key);
      const windowSize = 1000;
      const limit = 3;

      if (!entry) {
        state.set(key, { start: nowMs, count: 1 });
        return true;
      }

      if (nowMs >= entry.start + windowSize) {
        state.set(key, { start: nowMs, count: 1 });
        return true;
