export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const map = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL = 1000;

  const purge = (nowMs: number) => {
    for (const [key, { expiresAt }] of map.entries()) {
      if (nowMs >= expiresAt) {
        map.delete(key);
      }
    }
  };

  return {
    set(key, value, nowMs, ttlMs = DEFAULT_TTL) {
      map.set(key, { value, expiresAt: nowMs + ttlMs });
    },

    get(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },

    delete(key) {
      return map.delete(key);
    },

    size(nowMs) {
      purge(nowMs);
      return map.size;
    },

    clear() {
      map.clear();
    }
  };
}
