```typescript
export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  const isExpired = (expiresAt: number, nowMs: number): boolean => nowMs >= expiresAt;

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs ?? DEFAULT_TTL_MS;
      const expiresAt = nowMs + ttl;
      store.set(key, { value, expiresAt });
    },

    get(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (isExpired(entry.expiresAt, nowMs)) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return false;
      if (isExpired(entry.expiresAt, nowMs)) {
        store.delete(key);
        return false;
      }
      return true;
    },

    delete(key) {
      return store.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const [key, entry] of store.entries()) {
        if (isExpired(entry.expiresAt, nowMs)) {
          store.delete(key);
        } else {
          count++;
        }
      }
      return count;
    },

    clear() {
      store.clear();
    },
  };
}
