export function createCalculator(): Calculator {
  let value = 0;
  let memoryValue = 0;

  const calculator: Calculator = {
    add(n) { return updateValue('add', n); },
    subtract(n) { return updateValue('subtract', n); },
    multiply(n) { return updateValue('multiply', n); },
    divide(n) { return updateValue('divide', n); },
    clear() { value = 0; return calculator; },
    result() { return value; },
    memoryStore() { memoryValue = value; return calculator; },
    memoryRecall() { return memoryValue; },
    memoryClear() { memoryValue = 0; return calculator; },
    memoryAdd() { memoryValue += value; return calculator; }
  };

  function updateValue(operation: string, n: number): Calculator {
    switch (operation) {
      case 'add': value += n; break;
      case 'subtract': value -= n; break;
      case 'multiply': value *= n; break;
      case 'divide': value /= n; break;
    }
    return calculator;
  }

  return calculator;
