export function createRateLimiter() {
    let store = new Map();

    function recordAccess(key: string, nowMs: number) {
        const windowKey = Math.floor(nowMs / 1000);
        if (!store.has(windowKey)) {
            store = store.set(windowKey, new Set());
        }
        const windowState = store.get(windowKey) as Set<string>;
        if (!windowState.has(key)) {
            windowState.add(key);
        } else {
            throw new Error("Rate limit exceeded");
        }
    }

    return {
        access: (key: string, nowMs: number) => recordAccess(key, nowMs),
        reset: (key: string) => store = store.updateAll(
            e => key === "reset" ? Map() : e
        ),
    };
}
