import { Dictionary } from "lodash";

const LIMIT = 3;
const WINDOW_MS = 1000;

type KeyMap = Dictionary<{ attempts: number; lastCheckMs: number }>;

function createRateLimiter(): RateLimiter {
    const keyMap: KeyMap = {};

    function allow(key: string, nowMs: number): boolean {
        let entry = keyMap[key];
        if (!entry) {
            entry = { attempts: 0, lastCheckMs: 0 };
            keyMap[key] = entry;
        }

        const timeDiff = nowMs - entry.lastCheckMs;
        if (timeDiff >= WINDOW_MS || entry.attempts === 0) {
            entry.attempts = 1;
            entry.lastCheckMs = nowMs;
            return true; // First attempt after reset or window ends.
        }
        if (entry.attempts < LIMIT) {
            entry.attempts++;
            entry.lastCheckMs = nowMs;
            return true;
        }
        return false;
    }

    function remaining(key: string, nowMs: number): number {
        let entry = keyMap[key];
        if (!entry || allow(key, nowMs)) { // If not attempted or within policy
            return LIMIT - (entry?.attempts ?? 0);
        }
        return 0; // Already rejected for this window.
    }

    function reset(key: string): void {
        delete keyMap[key]; // Removes the entry completely resetting state.
    }

    return { allow, remaining, reset };
}
