import { Timestamp } from "firebase-admin/firestore";

export function createTtlCache(): TtlCache {
    const cache: Record<string, { value: unknown; expiresAt: number }> = {};

    function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
        if (ttlMs === undefined) ttlMs = 500;
        cache[key] = { value, expiresAt: nowMs + Math.max(1, ttlMs) };
    }

    function get(key: string, nowMs: number): unknown {
        const entry = cache[key];
        return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    }

    function has(key: string, nowMs: number): boolean {
        const entry = cache[key];
        return Boolean(entry && nowMs < entry.expiresAt);
    }

    function deleteKey(key: string): boolean {
        return delete cache[key];
    }

    function size(nowMs: number): number {
        let count = 0;
        for (const [key, entry] of Object.entries(cache)) {
            if (nowMs < entry.expiresAt) ++count;
        }
        return count;
    }

    const ttlCache: TtlCache = { set, get, has, delete: deleteKey, size, clear: () => (cache = {}) };

    return ttlCache;
}

interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
}
