type Listener<T = unknown> = (...args: unknown[]) => T;
type Listeners<T = unknown> = { listener: Listener<T>; once: boolean }[];

export function createEventEmitter() {
  const listeners: Record<string, Listeners> = {};

  function on<T>(event: string, listener: Listener<T>, once?: boolean): void {
    const eventListeners = listeners[event] || (listeners[event] = []);
    eventListeners.push({ listener, once: !!once });
  }

  function off<T>(event: string, listener: Listener<T>): void {
    const eventListeners = listeners[event];
    if (!eventListeners) return;

    const newListeners = eventListeners.filter((l) => l.listener !== listener);
    if (newListeners.length === 0) {
      delete listeners[event];
    } else {
      listeners[event] = newListeners;
    }
  }

  function emit<T>(event: string, ...args: unknown[]): T[] {
    const eventListeners = listeners[event];
    if (!eventListeners) return [];

    const results: T[] = [];
    const listenersToRemove: number[] = [];

    for (let i = 0; i < eventListeners.length; i++) {
      const { listener, once } = eventListeners[i];
      const result = listener(...args) as T;
      results.push(result);

      if (once) {
        listenersToRemove.push(i);
      }
    }

    if (listenersToRemove.length > 0) {
      const newListeners = eventListeners.filter(
        (_, index) => !listenersToRemove.includes(index)
      );
      if (newListeners.length === 0) {
        delete listeners[event];
      } else {
        listeners[event] = newListeners;
      }
    }

    return results;
  }

  function once<T>(event: string, listener: Listener<T>): void {
    on(event, listener, true);
  }

  return {
    on,
    off,
    emit,
    once,
  };
}
