export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const windows: Record<string, { count: number; startMs: number }> = {};

  return {
    allow(key, nowMs) {
      const window = this.getWindow(key, nowMs);
      if (window.count >= LIMIT) {
        return false;
      }
      window.count++;
      return true;
    },
    remaining(key, nowMs) {
      const window = this.getWindow(key, nowMs);
      return LIMIT - window.count;
    },
    reset(key) {
      delete windows[key];
    },
    getWindow(key, nowMs) {
      if (!(key in windows)) {
        windows[key] = { count: 0, startMs: nowMs };
      }
      const window = windows[key];
      if (nowMs - window.startMs >= WINDOW_MS) {
        window.count = 0;
        window.startMs = nowMs;
      }
      return window;
    },
  };
}
