    clearCompleted(): void {
      const filteredTodos = todos.filter((todo) => !todo.completed)
      // Ensure we don't mutate while iterating
      const temp = [...todos]
      temp.length = 0
      for (const todo of filteredTodos) {
        temp.push(todo)
      }
    },
  }
