export function createEventEmitter(): EventEmitter {
  const listeners: WeakMap<EventEmitter, Listener[]>[] = [];

  function getListeners(eventEmitter: EventEmitter): Listener[] | undefined {
    for (const listenerGroup of listeners) {
      if (listenerGroup.has(eventEmitter)) {
        return listenerGroup.get(eventEmitter);
      }
    }
    return undefined;
  }

  function addListener(
    eventEmitter: EventEmitter,
    event: string,
    listener: Listener
  ): number {
    let listenerGroup = getListeners(eventEmitter);

    if (!listenerGroup) {
      listenerGroup = new Map();
      listeners.push(listenerGroup);
    }

    const count = listenerGroup.size;
    listenerGroup.set(event, [...(listenerGroup.get(event) || []), listener]);
    return count + 1;
  }

  function onceListener(
    eventEmitter: EventEmitter,
    event: string,
    listener: Listener
  ): number {
    const tempListenerGroup = new Map();
    const normalCount = addListener(eventEmitter, event, listener);
    if (normalCount === 1) {
      listenerGroup.set(event, [listener]);
    }
    return normalCount;
  }

  function removeListener(
    eventEmitter: EventEmitter,
    event: string,
    listener: Listener
  ): boolean {
    let removed = false;
    for (const [key, valueMap] of listeners.entries()) {
      if (key === eventEmitter) {
        const existingListeners = valueMap.get(event);
        if (existingListeners) {
          const index = existingListeners.indexOf(listener);
          if (index !== -1) {
            existingListeners.splice(index, 1);
            removed = true;
            if (valueMap.size === 0) {
              listeners.delete(key);
            }
          }
        }
      }
    }
    return removed;
  }

  function emit(eventEmitter: EventEmitter, event: string, payload: unknown): unknown[] {
    const listenerGroup = getListeners(eventEmitter);
    if (!listenerGroup) return [];

    const listenersArray = listenerGroup.get(event) || [];
    const results: unknown[] = [];
    for (const listener of listenersArray) {
      results.push(listener(payload));
    }
    return results;
  }

  function listenerCount(eventEmitter: EventEmitter, event: string): number {
    const listenerGroup = getListeners(eventEmitter);
    if (!listenerGroup) return 0;

    const listenersArray = listenerGroup.get(event) || [];
    return listenersArray.length;
  }

  return Object.assign(
    (event: string, listener: Listener): number => addListener(eventEmitter, event, listener),
    (event: string, listener: Listener): number => onceListener(eventEmitter, event, listener),
    (event: string, listener: Listener): boolean => removeListener(eventEmitter, event, listener),
    (event: unknown[], payload: unknown): unknown[] => emit(eventEmitter, event as string, payload),
    (event: string): number => listenerCount(eventEmitter, event)
  );
}
