export function createRateLimiter(nowMs: () => number): {
    check(key: string): boolean;
    reset(key: string);
} {
    const buckets = new Map<string, number[]>();

    const windowSizeMs = 1000; // 1 second
    const requestsPerWindow = 3;

    function getOrInitBucket(key: string): number[] {
        if (!buckets.has(key)) {
            buckets.set(key, Array(windowSizeMs).fill(0));
        }
        return buckets.get(key)!;
    }

    function check(key: string): boolean {
        const bucket = getOrInitBucket(key);
        const nowBucketIndex = Math.floor(nowMs() / windowSizeMs);

        for (let i = 1; i < requestsPerWindow + 1; i++) {
            if (bucket[nowBucketIndex - i] === 0) {
                return true;
            }
        }

        return false;
    }

    function reset(key: string): void {
        const bucket = getOrInitBucket(key);
        const nowBucketIndex = Math.floor(nowMs() / windowSizeMs);

        for (let i = 1; i < requestsPerWindow + 1; i++) {
            if (bucket[nowBucketIndex - i] >= 0) {
                bucket[nowBucketIndex - i] = -1;
            }
        }

        const firstValidIndex = nowBucketIndex - requestsPerWindow + 1;
        for (let i = firstValidIndex; i < nowBucketIndex; i++) {
            bucket[i] = 0;
        }
    }

    return { check, reset };
}
