export function createRateLimiter(): (key: string) => RateLimiter {
  const throttles = new Map<string, Throttle>();

  function Throttle() {
    this.reset();
  }

  Throttle.prototype = {
    limit: 3,
    windowMs: 1000,
    lastCallTimestamp: Infinity,

    reset() {
      this.lastCallTimestamp = Date.now() - this.windowMs;
    },

    allow(nowMs: number): boolean {
      const elapsed = nowMs - this.lastCallTimestamp;

      if (elapsed >= this.windowMs) {
        this.reset();
      }

      return (
        this.throttleState.length < this.limit &&
        !this.throttleState.includes(elapsed)
      );
    },

    remaining(nowMs: number): number {
      const activeCalls = this.throttleState.filter(
        (interval, index) => nowMs - interval <= this.windowMs
      );

      return this.limit - activeCalls.length;
    },

    reset(key: string) {
      if (!throttles.has(key)) return;

      throttles.get(key)?.reset();
    }
  };

  return key => {
    if (throttles.has(key)) {
      const throttle = throttles.get(key);
      if (throttle && throttle.allow(nowMs)) {
        if (throttle.throttleState.length < this.limit) {
          throttle.throttleState.push(nowMs - throttle.lastCallTimestamp);
        }
        return true;
      }
    } else {
      throttles.set(key, new Throttle());
    }

    return false;
  };
}
