export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const entries: { [key: string]: { value: unknown; expiresAt: number } } = {};

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    if (ttlMs === undefined) {
      ttlMs = 1000;
    }
    entries[key] = { value, expiresAt: nowMs + ttlMs };
  }

  function get(key: string, nowMs: number): unknown {
    const entry = entries[key];
    return entry ? entry.value : undefined;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = entries[key];
    return entry !== undefined && nowMs < entry.expiresAt;
  }

  function deleteKey(key: string) {
    if (entries.hasOwnProperty(key)) {
      delete entries[key];
      return true;
    }
    return false;
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const key in entries) {
      const entry = entries[key];
      if (entry && nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  function clear() {
    Object.keys(entries).forEach(deleteKey);
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear
  };
}
