export function createTtlCache(): TtlCache {
  const cache: Record<string, { value: unknown; expiresAt: number }> = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      cache[key] = {
        value,
        expiresAt: nowMs + (ttlMs === 0 ? -Infinity : ttlMs),
      };
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (!entry || nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const value = this.get(key, nowMs);
      return value !== undefined;
    },
    delete(key: string): boolean {
      return delete cache[key];
    },
    size(nowMs: number): number {
      return Object.values(cache)
        .filter((entry) => nowMs < entry.expiresAt)
        .length;
    },
    clear(): void {
      cache = {};
    }
  };
}
