export function createEventEmitter() {
    return {
        on: <K extends string>(
            eventName: K,
            listener: (event: K extends string ? K : never) => void | any
        ): void => {
            if (!(eventName in this._listeners)) {
                (this as any)._listeners[eventName] = [];
            }
            (this as any)._listeners[eventName].push(listener);
        },
        off: <K extends string>(
            eventName: K,
            listener: (event: K extends string ? K : never) => void | any
        ): void => {
            const listeners = this._listeners?.[eventName] || [];
            const originalListeners = [...listeners];
            listeners.length = 0; // Clear existing entries to simplify removal
            originalListeners.forEach((lstnr) => {
                if (lstnr === listener || ((lstnr as Function).toString() === (listener as Function).toString())) {
                    return; // This avoids comparison through `===` with function objects (non-strict)
                }
                listeners.push(lstnr);
            });
            (this as any)._listeners[eventName] = listeners;
        },
        once: <K extends string>(
            eventName: K,
            listener: (event: K extends string ? K : never) => void | any
        ): void => {
            const originalListener = listener;
            const listenerWrapper = (...args: any[]) => {
                const result = listener(...args);
                this.off(eventName, originalListener);
                return result;
            };
            this.on(eventName, listenerWrapper);
        },
        emit: <K extends string>(
            eventName: K,
            ...args: Parameters<(event: K extends string ? K : never) => void | any>
        ): ReturnType<(event: K extends string ? K : never) => void | any>[] => {
            const listeners = (this as any)._listeners[eventName] || [];
            const returnValues: any[] = [];
            listeners.forEach((listener) => {
                const result = listener.apply(void 0, ...args);
                if (result !== undefined) {
                    returnValues.push(result);
                }
            });
            return returnValues;
        },
        _listeners: Record<string, ((...args: any[]) => void | any)[] | null> = {},
    };
}
