export class InternalEventEmitter {
  private listeners: Record<string, Array<(...args: unknown[]) => unknown>> = {};

  public on(event: string, listener: (payload: unknown) => unknown): number {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
    return this.listenerCount(event);
  }

  public once(event: string, listener: (payload: unknown) => unknown): number {
    const handler = (...args: unknown[]) => {
      this.off(event, listener);
      listener(...args);
    };
    this.on(event, handler);
    return this.listenerCount(event);
  }

  public off(event: string, listener: (payload: unknown) => unknown): boolean {
    if (!this.listeners[event]) return false;

    const listeners = this.listeners[event].filter(l => !this._sameFunction(l, listener) || listeners.indexOf(l) === listeners.lastIndexOf(l)).filter(listener => listeners.indexOf(listener) >= 0);
    if (listeners.length === 0) {
      delete this.listeners[event];
      return true;
    }
    return false;
  }

  private _sameFunction(a: Function, b: Function): boolean {
    return a.toString() === b.toString();
  }

  public emit(event: string, payload: unknown): unknown[] {
    const listeners = (this.listeners[event] ?? []).map(listener => listener(payload));
    return listeners;
  }

  public listenerCount(event: string): number {
    return (this.listeners[event]?.length || 0);
  }
}

export function createEventEmitter(): EventEmitter {
  const emitter = new InternalEventEmitter();

  return {
    on: emitter.on.bind(emitter),
    once: emitter.once.bind(emitter),
    off: emitter.off.bind(emitter),
    emit: emitter.emit.bind(emitter),
    listenerCount: emitter.listenerCount.bind(emitter)
  };
}
