export function createRateLimiter() {
  const rateLimits = new Map<string, {
    startMs: number;
    count: number;
  }>();

  return {
    rateLimit(key: string, nowMs: number): boolean {
      const entry = rateLimits.get(key);
      const windowStart = nowMs - (nowMs % 1000) & ~(nowMs % 1000);

      if (!entry || entry.startMs !== windowStart) {
        rateLimits.set(key, { startMs: windowStart, count: 1 });
        return true;
      }

      if (entry.count < 3) {
        entry.count += 1;
        return true;
      }

      return false;
    },
    reset(key: string) {
      rateLimits.delete(key);
    }
