export function createRateLimiter(): RateLimiter {
  const state: Record<string, { windowStart: number; uses: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const nowInWindow: number = (nowMs - (nowMs % 1000));
      const keyWindowData = state[key] ?? { windowStart: 0, uses: 0 };

      if (
        (nowMs - keyWindowData.windowStart) >= 1000 ||
        keyWindowData.uses >= 3
      ) {
        state[key] = { windowStart: nowInWindow, uses: 0 };
        return true;
      }

      const attemptsLeft = 3 - keyWindowData.uses;
      keyWindowData.uses += 1;
      state[key] = { ...keyWindowData };
      return attemptsLeft > 0;
    },
    remaining(key: string, nowMs: number): number {
