export function createTtlCache(): {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => void;
    get: (key: string, nowMs: number) => unknown;
    has: (key: string, nowMs: number) => boolean;
    delete: (key: string) => boolean;
    size: (nowMs: number) => number;
    clear: () => void;
} {
    const cacheMap = new Map<string, { value: unknown; expiresAt: number }>();

    return {
        set: (key: string, value: unknown, nowMs: number, ttlMs = 1000): void => {
            const expiresAt = nowMs + (ttlMs || 1000);
            cacheMap.set(key, { value, expiresAt });
        },
        get: (key: string, nowMs: number): unknown => {
            const entry = cacheMap.get(key);
            if (!entry?.expiresAt || nowMs < entry.expiresAt) {
                return entry?.value;
            }
            return undefined;
        },
        has: (key: string, nowMs: number): boolean => {
            const entry = cacheMap.get(key);
            if (!entry?.expiresAt || nowMs < entry.expiresAt) {
                return true;
            }
            return false;
        },
        delete: (key: string): boolean => {
            const existing = cacheMap.get(key);
            if (!existing) return false;
            cacheMap.delete(key);
            return true;
        },
        size: (nowMs: number): number => {
            const liveKeys = new Set<string>();
            for (const [key, entry] of cacheMap) {
                if (!entry?.expiresAt || nowMs < entry.expiresAt) {
                    liveKeys.add(key);
                }
            }
            return liveKeys.size === cacheMap.size ? cacheMap.size : liveKeys.size;
        },
        clear: (): void => {
            cacheMap.clear();
        },
    };
}
