    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      return Array.from(cache.entries())
        .filter(([_, { expiresAt }]) => nowMs < expiresAt)
        .length;
    },
    clear() {
      cache.clear();
    },
  };
}

