export const createEventEmitter = (eventName: string, listenerId: string) => {
  const listeners = {};
  const addListener = (id: string, isOneTime: boolean, callback: (...args: any[]) => any) => {
    if (!listeners[eventName]) {
      listeners[eventName] = [];
    }
    const newListener = {
      id,
      isOneTime,
      callback
    };
    listeners[eventName].push(newListener);
  };

  const removeListener = (id: string) => {
    if (listeners[eventName]) {
      listeners[eventName] = listeners[eventName].filter((l) => l.id !== id);
    }
  };

  const emit = (args: any[]) => {
    const results = [];
    let i = 0;
    while (i < listeners[eventName].length) {
      const listener = listeners[eventName][i];
      if (listener.isOneTime) {
        results.push(listener.callback(...args));
        i++;
      } else {
        results.push(listener.callback(...args));
        i++;
      }
    }
    return results;
  };

  return {
    add: addListener,
    remove: removeListener,
    emit
  };
