type RateLimiterKey = { count: number; windowStart: number };

export const createRateLimiter = (nowMs: number): RateLimiterKey => {
  const key = { count: 0, windowStart: nowMs };
  return { ...key };
};

export const increment = (key: RateLimiterKey, nowMs: number): RateLimiterKey => {
  if (nowMs < key.windowStart) {
    key.count = 0;
    key.windowStart = nowMs;
  }
  key.count++;
  return key;
};

export const reset = (key: RateLimiterKey) => {
  key.count = 0;
  key.windowStart = nowMs;
  return key;
};

export const isAllowed = (key: RateLimiterKey, nowMs: number): boolean => {
  if (nowMs < key.windowStart) {
    return true;
  }
  if (key.count >= 3) {
    return false;
  }
  key.windowStart = nowMs;
  key.count++;
  return key.count < 3;
};
