export function createRateLimiter(): RateLimiter {
  const limiter = {};

  interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
  }

  return {
    allow(key, nowMs) {
      if (!key) return false;
      const windowStart = limiter[key] || 0;
      const windowMs = 1000;
      if (nowMs - windowStart >= windowMs) {
        limiter[key] = nowMs;
      }
      return nowMs - windowStart < windowMs && limiter[key] > nowMs;
    },
    remaining(key, nowMs) {
      if (!key) return 0;
      const windowStart = limiter[key] || 0;
      return Math.max(0, windowMs - (nowMs - windowStart));
    },
    reset(key) {
      if (!key) return;
      limiter[key] = undefined;
    }
  };
}
