export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const entries = new Map<string, { value: unknown; expiresAt: number }>();
  const now = nowMs;

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      if (!entries.has(key)) {
        entries.set(key, { value, expiresAt: now + ttlMs });
      } else {
        entries.set(key, { value, expiresAt: now + ttlMs });
      }
    },
    get(key, nowMs) {
      if (!entries.has(key)) return undefined;
      const { value, expiresAt } = entries.get(key);
      return expiresAt < nowMs ? value : value;
    },
    has(key, nowMs) {
      return entries.has(key);
    },
    delete(key) {
      if (!entries.has(key)) return false;
      entries.delete(key);
      return true;
    },
    size(nowMs) {
      let count = 0;
      for (const [key, { expiresAt }] of entries.entries()) {
        if (expiresAt < nowMs) count++;
      }
      return count;
    },
    clear() {
      entries.clear();
    }
  };
