export function createTtlCache(): TtlCache {
  class TtlCache {
    private entries: Map<string, { value: unknown; expiresAt: number; }>;
    private defaultTtl: number = 1000;

    constructor() {
      this.entries = new Map();
    }

    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (ttlMs === undefined) {
        ttlMs = this.defaultTtl;
      }
      const expiresAt = nowMs + ttlMs;
      this.entries.set(key, { value, expiresAt });
    }

    get(key: string, nowMs: number): unknown {
      const entry = this.entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    }

    has(key: string, nowMs: number): boolean {
      const entry = this.entries.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    }

    delete(key: string): boolean {
      const entry = this.entries.get(key);
      if (!entry) return false;
      this.entries.delete(key);
      return true;
    }

    size(nowMs: number): number {
      let count = 0;
      for (const [key, { expiresAt }] of this.entries.entries()) {
        if (nowMs < expiresAt) {
          count++;
        }
      }
      return count;
    }

    clear(): void {
      this.entries.clear();
    }
  }

  return new TtlCache();
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
