export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { regular: Listener[], once: Listener[] }>();

  return {
    on(event: string, listener: Listener): number {
      const entry = listeners.get(event) || { regular: [], once: [] };
      entry.regular.push(listener);
      listeners.set(event, entry);
      return entry.regular.length;
    },
    once(event: string, listener: Listener): number {
      const entry = listeners.get(event) || { regular: [], once: [] };
      const wrapper = (payload: unknown) => {
        const index = entry.once.indexOf(wrapper);
        if (index !== -1) {
          entry.once.splice(index, 1);
        }
        return listener(payload);
      };
      entry.once.push(wrapper);
      listeners.set(event, entry);
      return entry.once.length;
    },
    off(event: string, listener: Listener): boolean {
      const entry = listeners.get(event);
      if (!entry) return false;
      const index = entry.regular.indexOf(listener);
      if (index !== -1) {
        entry.regular.splice(index, 1);
        return true;
      }
      const onceIndex = entry.once.indexOf(listener);
      if (onceIndex !== -1) {
        entry.once.splice(onceIndex, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const entry = listeners.get(event);
      if (!entry) return [];
      const results: unknown[] = [];
      for (const listener of entry.regular) {
        results.push(listener(payload));
      }
      for (const listener of entry.once) {
        results.push(listener(payload));
      }
      return results;
    },
    listenerCount(event: string): number {
      const entry = listeners.get(event);
      if (!entry) return 0;
      return entry.regular.length + entry.once.length;
    }
  };
}
