```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

class EventEmitterImpl implements EventEmitter {
  private eventListeners: Record<string, { regular: Listener[]; once: Listener[] }> = {};

  on(event: string, listener: Listener): number {
    if (!this.eventListeners[event]) {
      this.eventListeners[event] = { regular: [], once: [] };
    }
    this.eventListeners[event].regular.push(listener);
    return this.eventListeners[event].regular.length;
  }

  once(event: string, listener: Listener): number {
    if (!this.eventListeners[event]) {
      this.eventListeners[event] = { regular: [], once: [] };
    }
    this.eventListeners[event].once.push(listener);
    return this.eventListeners[event].once.length;
  }

  off(event: string, listener: Listener): boolean {
    if (!this.eventListeners[event]) return false;

    const { regular, once } = this.eventListeners[event];
    const foundInRegular = regular.indexOf(listener) !== -1;
    if (foundInRegular) {
      regular.splice(regular.indexOf(listener), 1);
      return true;
    }
    const foundInOnce = once.indexOf(listener) !== -1;
    if (foundInOnce) {
      once.splice(once.indexOf(listener), 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventInfo = this.eventListeners[event];
    if (!eventInfo) return [];

    const result: unknown[] = [];
    eventInfo.regular.forEach(listener => {
      result.push(listener(payload));
    });

    for (let i = 0; i < eventInfo.once.length; i++) {
      const listener = eventInfo.once[i];
      result.push(listener(payload));
      eventInfo.once.splice(i, 1);
    }
    return result;
  }

  listenerCount(event: string): number {
    const eventInfo = this.eventListeners[event];
    return eventInfo ? eventInfo.regular.length + eventInfo.once.length : 0;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl();
}
