  reset(key: string): void;
}

class RateLimiter {
  private cache = new Map<string, { count: number; windowStart: number }>();

  constructor() {}

  allow(key: string, nowMs: number): boolean {
    const state = this.cache.get(key);
    if (!state) {
      this.cache.set(key, { count: 0, windowStart: nowMs });
      return true;
    }

    const timeSince = nowMs - state.windowStart;
    if (timeSince >= 1000) {
      this.cache.set(key, { count: 0, windowStart: nowMs });
    }

    if (state.count < 3) {
      this.cache.set(key, { count: state.count + 1, windowStart: state.windowStart });
      return true;
    }

    return false;
  }

  remaining(key: string, nowMs: number): number {
    const state = this.cache.get(key);
    if (!state) {
      return 3;
    }

    const timeSince = nowMs - state.windowStart;
    if (timeSince >= 1000) {
      this.cache.set(key, { count: 0, windowStart: nowMs });
    }

    return 3 - state.count;
  }

  reset(key: string): void {
    this.cache.delete(key);
  }
}

export function createRateLimiter(): RateLimiter {
  return new RateLimiter();
}
