export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    cache.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number) => {
    const entry = cache.get(key);
    return entry && nowMs < entry.expiresAt ? entry.value : undefined;
  };

  const has = (key: string, nowMs: number) => {
    const entry = cache.get(key);
    return entry && nowMs < entry.expiresAt;
  };

  const deleteEntry = (key: string) => {
    const exists = cache.has(key);
    cache.delete(key);
    return exists;
  };

  const size = (nowMs: number) => {
    return Array.from(cache).reduce((count, entry) => {
      return entry[1].expiresAt > nowMs ? count + 1 : count;
    }, 0);
  };

  const clear = () => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete: deleteEntry,
    size,
    clear
  };
}
