export function createTtlCache() {
  const map = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  const api = {
    set(
      key: string,
      value: unknown,
      nowMs: number,
      ttlMs: number = DEFAULT_TTL_MS
    ): void {
      map.set(key, { value, expiresAt: nowMs + ttlMs });
    },

    get(key: string, nowMs: number): unknown {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return map.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      const keysToDelete: string[] = [];
      for (const [key, entry] of map.entries()) {
        if (nowMs >= entry.expiresAt) {
          keysToDelete.push(key);
        } else {
          count++;
        }
      }
      for (const key of keysToDelete) {
        map.delete(key);
      }
      return count;
    },

    clear(): void {
      map.clear();
    },
  };

  return api;
}

export function createTtlCache(): TtlCache {
  const DEFAULT_TTL_MS = 1000;
  const store = new Map<
    string,
    { value: unknown; expiresAt: number }
  >();

  const cleanEntry = (key: string, nowMs: number) => {
    const entry = store.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  };

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs !== undefined ? ttlMs : DEFAULT_TTL_MS;
      const expiresAt = nowMs + ttl;
      store.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      return cleanEntry(key, nowMs);
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of store.entries()) {
        if (nowMs >= entry.expiresAt) {
          store.delete(key);
        } else {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    },
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
