export function createCalculator(): Calculator {
  let currentValue = 0;
  let memory = 0;

  const calculator = Object.assign(
    function (): number {
      return this.result();
    },
    new Proxy({}, {
      get: (target, key) => {
        if (typeof key === 'string' && calculator[key] !== undefined) {
          return (...args: any[]) => {
            return calculate(calculator[key]).apply(calculator, args);
          };
        }
        throw new Error(`Calculator method ${key} does not exist`);
      },
    })
  );

  function calculate(operation) {
    switch (operation) {
      case 'add':
        currentValue += arguments[0];
        break;
      case 'subtract':
        currentValue -= arguments[0];
        break;
      case 'multiply':
        currentValue *= arguments[0];
        break;
      case 'divide':
        if (arguments[0] === 0) throw new Error('Division by zero is not allowed');
        currentValue /= arguments[0];
        break;
      case 'clear':
        currentValue = 0;
        break;
      case 'memoryStore':
        memory = currentValue;
        break;
      case 'memoryAdd':
        memory += currentValue;
        break;
      case 'result':
        return currentValue;
      case 'memoryRecall':
        return memory;
      default:
        throw new Error(`Invalid operation: ${operation}`);
    }
  }

  function clearCalculator() {
    currentValue = 0;
    memory = 0;
  }

  calculator.add = (...args) => calculate('add', args);
  calculator.subtract = (...args) => calculate('subtract', args);
  calculator.multiply = (...args) => calculate('multiply', args);
  calculator.divide = (...args) => calculate('divide', args);
  calculator.clear = () => (calculate('clear'), calculator);
  calculator.memoryStore = () => (calculate('memoryStore'), calculator);
  calculator.result = () => calculate('result');
  calculator.memoryRecall = () => calculate('memoryRecall');
  calculator.memoryClear = clearCalculator;
  calculator.clear();

  return Object.freeze(calculator);
}

