function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, Array<[Listener, boolean]>>();

  function on(eventName: string, listener: Listener) {
    addListeners(eventName, listener, false);
  }

  function once(eventName: string, listener: Listener) {
    addListeners(eventName, (...args) => { 
      listener(...args); 
      off(eventName, listener); 
    }, true);
  }

  function off(eventName: string, listener?: Listener) {
    const list = listenersMap.get(eventName) || [];
    if (listener === undefined) {
      listenersMap.set(eventName, []);
    } else {
      for (let i = 0; i < list.length; i++) {
        if ((list[i][1] && !list[i][0]) || (!list[i][1] && list[i][0])) {
          list.splice(i--, 1);
        }
      }
    }
  }

  function emit(eventName: string, ...args: any[]): Listener[] {
    const eventListeners = listenersMap.get(eventName) || [];
    return eventListeners
      .map(entry => [	entry[0], entry[entry] ])
      .filter(([listener]) => listener)
      .flat()
      .filter(listener => !!(listener as (...any) => void).apply(null, args));
  }

  function addListeners(eventName: string, newListener: Listener, onceFlag = false) {
    const existingEventsList = listenersMap.get(eventName);
    if (!existingEventsList) {
      const newEventList = [[newListener, onceFlag]];
      listenersMap.set(eventName, newEventList);
    } else {
      existingEventsList.push([newListener, onceFlag]);
    }
  }

  return { on, off, emit, once };
}

