export function createRateLimiter(): RateLimiter {
  const store = new Map<string, { nextAllowTime: number; remainingRequests: number }>();

  function ensureKey(key: string) {
    if (!store.has(key)) {
      store.set(key, { nextAllowTime: Date.now(), remainingRequests: 0 });
    }
  }

  return {
    allow(key: string, nowMs: number): boolean {
      ensureKey(key);
      const state = store.get(key)!;

      if (nowMs - state.nextAllowTime >= 1000) {
        reset(key); // start fresh window
      }

      if (state.remainingRequests > 0) {
        state.remainingRequests--;
        state.nextAllowTime += 1000;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      ensureKey(key);
      const state = store.get(key)!;

      if (nowMs - state.nextAllowTime >= 1000) {
        reset(key); // start fresh window
      }

      return Math.max(3 - state.remainingRequests, 0);
    },

    reset(key: string): void {
      ensureKey(key);
      const nextAllow = Date.now();
      store.set(key, { nextAllowTime: nextAllow, remainingRequests: 3 });
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
