export function createTodoApp() {
  let todos: { id: number, text: string, completed: boolean }[] = [];

  const addTodo = (text: string) => {
    const todo = { id: Number(new Date()), text, completed: false };
    todos.push(todo);
    return todo;
  };

  const getTodo = (id: number) => todos.find(t => t.id === id);

  const toggleTodo = (id: number) =>
    todos.forEach((todo) => {
      if (todo.id === id) {
        todo.completed = !todo.completed;
      }
    });

  const deleteTodo = (id: number): boolean =>
    todos.filter(todo => todo.id !== id).length < todos.length;

  const listTodos = () => todos.slice();

  const listCompleted = () => todos.filter(t => t.completed);

  const listPending = () => todos.filter(t => !t.completed);

  const clearCompleted = () =>
    todos.splice(0, todos.length, ...todos.filter(t => !t.completed));

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}
