export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, [unknown, number]>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      if (cache.has(key)) {
        cache.delete(key);
      }
      cache.set(key, [value, nowMs + ttlMs]);
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      return entry && entry[1] > nowMs ? entry[0] : undefined;
    },
    has(key, nowMs) {
      return this.get(key, nowMs) !== undefined;
    },
    delete(key) {
      return Boolean(cache.delete(key));
    },
    size(nowMs) {
      let count = 0;
      for (const [expireTime] of cache.values()) {
        if (expireTime > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    },
  };
}
