import { Map } from 'typescript-collections';

export function createTtlCache(): TtlCache {
    const cache = new Map<string, CacheEntry>();

    function refresh(key: string, nowMs: number) {
        if (cache.has(key)) {
            const entry = cache.getValue(key)!;
            cache.setValue(key, { ...entry, updateTime: nowMs });
        }
    }

    class CacheEntry {
        value: unknown;
        expiresAt: number;

        constructor(value: unknown, ttlMs?: number, nowMs?: number) {
            this.value = value ?? undefined; // Handle storing undefined values
            if (ttlMs === 0) { this.expiresAt = nowMs! - 1; } 
            else { this.expiresAt = nowMs! + ttlMs || 1000; } // Default TTL of 1s or use given ttl
        }
    }

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
            let currentEntry = cache.getValue(key);
            if (currentEntry && !isExpired(currentEntry.expiresAt)) {
                refresh(key, nowMs); // refresh existing entry's timing info
            }
            cache.setValue(key, new CacheEntry(value, ttlMs, nowMs));
        },
        get(key: string, nowMs: number) {
            const entry = isTtlCache(cache.getValue(key));
            return (entry && !isExpired(entry.expiresAt)) ? entry.value : undefined;
        },
        has(key: string, nowMs: number) {       
            return cache.getKeyValueMap()
                .hasKeyValue(key, (entry: CacheEntry | null) => 
                    isTtlCache(entry) && !isExpired(entry!.expiresAt));  
        },     
        delete(key: string) {
            const deleted = cache.remove(key);
            return !!deleted;
        },
        size(nowMs: number): number {
            return Array.from(cache.getKeyValueMap())
                .filter(kv => 
                    isTtlCache(kv[1]) && !isExpired(kv[0][1].expiresAt))
                .length;   
        },
        clear() {
            cache.clear();
        },  
    };
}

function isExpired(expiresAt: number) {
    return Date.now() >= expiresAt;
}
