type Listener<T> = () => T;
type OneTimeListener<T> = Listener<T> & { _oneTime: true };
type Listeners = Array<Listener<any>>;

function isOneTimeListener<T>(listener: Listener<T> | OneTimeListener<T>): listener is OneTimeListener<T> {
  return (listener as OneTimeListener<T>)._oneTime === true;
}

function createEventEmitter<T>(): {
  on: <E>(event: string, listener: Listener<E>) => void;
  once: <E>(event: string, listener: Listener<E>) => void;
  off: <E>(event: string, listener: Listener<E>) => void;
  emit: <E>(event: string, ...args: E[]) => E[];
} {
  const listeners: Record<string, Listeners> = {};
  return {
    on<E>(event: string, listener: Listener<E>): void {
      const existing = listeners[event] || [];
      existing.push(listener);
      listeners[event] = existing;
    },
    once<E>(event: string, listener: Listener<E>): void {
      const existing = listeners[event] || [];
      const oneTimeListener = { ...listener, _oneTime: true };
      existing.push(oneTimeListener);
      listeners[event] = existing;
    },
    off<E>(event: string, listener: Listener<E>): void {
      const existing = listeners[event];
      if (!existing) return;
      const index = existing.findIndex(l => l === listener);
      if (index >= 0) {
        existing.splice(index, 1);
      }
    },
    emit<E>(event: string, ...args: E[]): E[] {
      const existing = listeners[event] || [];
      existing.forEach((listener, index) => {
        listener(...args);
        if (isOneTimeListener(listener)) {
          existing.splice(index, 1);
        }
      });
      return [];
    }
  };
}

export { createEventEmitter };
