export function createCalculator() {
  let currentValue = 0;
  let memoryValue = 0;

  const add = (value: number): this => {
    currentValue += value;
    return this;
  };

  const subtract = (value: number): this => {
    currentValue -= value;
    return this;
  };

  const multiply = (value: number): this => {
    currentValue *= value;
    return this;
  };

  const divide = (value: number): this => {
    if (value === 0) throw new Error('Division by zero');
    currentValue /= value;
    return this;
  };

  const clear = (): this => {
    currentValue = 0;
    return this;
  };

  const result = (): number => currentValue;

  const memoryStore = (): this => {
    memoryValue = currentValue;
    return this;
  };

  const memoryAdd = (): this => {
    memoryValue += currentValue;
    return this;
  };

  const memoryClear = (): this => {
    memoryValue = 0;
    return this;
  };

  const memoryRecall = (): { result: number; memory: number } => ({
    result: currentValue,
    memory: memoryValue,
  });

  return Object.assign(({}), {
    add,
    subtract,
    multiply,
    divide,
    clear,
    result,
    memoryStore,
    memoryAdd,
    memoryClear,
    memoryRecall,
  });
}
