export function createEventEmitter() {
    const listeners = new Map<string, ((...args: any[]) => any)[]>();

    return {
        on(eventName: string, listener: (...args: any[]) => any) {
            if (!listeners.has(eventName)) {
                listeners.set(eventName, []);
            }
            listeners.get(eventName)?.push(listener);
        },
        once(eventName: string, listener: (...args: any[]) => any) {
            const onceListener = (args: any[]) => {
                listener(...args);
                this.off(eventName, onceListener);
            };
            this.on(eventName, onceListener);
        },
        off(eventName: string, listener: (...args: any[]) => any) {
            if (!listeners.has(eventName)) return;
            listeners.get(eventName)?.forEach((l, i) => {
                if (l === listener) {
                    listeners.get(eventName)?.splice(i, 1);
                }
            });
        },
        emit(eventName: string, ...args: any[]): any[] {
            const eventListeners = listeners.get(eventName);
            if (!eventListeners) return [];
            return eventListeners.map(l => l(...args));
        }
    };
}
