export function createEventEmitter(): EventEmitter {
  const events: Record<string, Listener[]> = {};

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push(listener);
      return events[event].length;
    },

    once(event: string, listener: Listener): number {
      const onceListener = (payload: unknown) => {
        listener(payload);
        this.off(event, onceListener);
      };

      const count = this.on(event, onceListener);
      return count;
    },

    off(event: string, listener: Listener): boolean {
      if (!events[event]) {
        return false;
      }

      events[event] = events[event].filter((existingListener) => existingListener !== listener);

      return Boolean(events[event].length);
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!events[event]) {
        return [];
      }

      const listeners = [...events[event]];
      const results: unknown[] = [];

      for (const listener of listeners) {
        const result = listener(payload);
        results.push(result);
      }

      return results;
    },

    listenerCount(event: string): number {
      return events[event]?.length || 0;
    }
  };
}
