export function createRateLimiter(nowMs: () => number) {
    const quotas = new Map<string, { lastRequestTime: number; requestCount: number }>();

    return {
        reset(key: string): void {
            quotas.delete(key);
        },

        allow(key: string): boolean {
            const now = nowMs();
            let quotaEntry = quotas.get(key);

            if (!quotaEntry) {
                quotaEntry = { lastRequestTime: 0, requestCount: 0 };
                quotas.set(key, quotaEntry);
            }

            if (now - quotaEntry.lastRequestTime >= 1000) {
                quotaEntry.requestCount = 1;
                quotaEntry.lastRequestTime = now;
                return true;
            } else if (quotaEntry.requestCount < 3) {
                quotaEntry.requestCount++;
                return true;
            }

            return false;
        }
    };
}
