export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  const todoIds: Map<Todo, number> = new Map();

  return {
    addTodo(text: string): Todo {
      const id = Math.max(...Array.from(todoIds.values()) || [0]) + 1;
      const newTodo: Todo = { id, text, completed: false };
      todos.push(newTodo);
      todoIds.set(newTodo, id);
      return newTodo;
    },
    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id);
    },
    toggleTodo(id: number): void {
      const todo = this.getTodo(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },
    deleteTodo(id: number): boolean {
      const todo = this.getTodo(id);
      if (!todo) return false;

      for (const [index, t] of todos.entries()) {
        if (t.id === id) {
          todos.splice(index, 1);
          break;
        }
      }

      todoIds.delete(todo);

      return true;
    },
    listTodos(): Todo[] {
      return [...todos];
