export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  function nowMsPlus(ttlMs?: number): number {
    return ttlMs ? nowMs + ttlMs : nowMs + 1000;
  }

  function expiresIn(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    if (entry) {
      return nowMs < entry.expiresAt;
    }
    return false;
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const expiresAt = nowMsPlus(ttlMs);
      cache.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      if (expiresIn(key, nowMs)) {
        return cache.get(key)?.value;
      }
      return undefined;
    },
    has(key: string, nowMs: number): boolean {
      if (expiresIn(key, nowMs)) {
        return true;
      }
      return false;
    },
    delete(key: string): boolean {
      const result = cache.delete(key);
      return result && expiresIn(key, nowMs);
    },
    size(nowMs: number): number {
      return Array.from(cache.values()).filter((entry) => expiresIn(entry.key, nowMs)).length;
    },
    clear() {
      cache.clear();
    }
  };
}
