  private events: Map<string, Array<(payload: unknown) => unknown>> = new Map();

  private cleanup = (event: string) => {
    this.events.delete(event);
  };

  emit(event: string, payload: unknown) {
    if (this.events.has(event)) {
      const listeners = thisevents.get(event)!.slice();
      const returnValues = listeners.map(listener => listener(payload));
      this.cleanup(event);
      return returnValues;
    }
    return [];
  }

  listenerCount(event: string) {
    return this.events.has(event) ? this.events.get(event)!.length : 0;
  }

  on(event: string, listener: (payload: unknown) => unknown) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    this.events.get(event)!.push(listener);
    return this.listenerCount(event);
  }

  once(event: string, listener: (payload: unknown) => unknown) {
    const onceListener = (payload: unknown) => {
      const listeners = this.events.get(event)!.slice();
      listeners.forEach(registeredListener => registeredListener(payload));
      this.off(event, listener);
