    if (!this.events.has(event)) {
      return false;
    }

    const currentListeners = thisevents.get(event)!;
    const filteredListeners = currentListeners.filter(
      l => l !== listener
    );

    if (filteredListeners.length === currentListeners.length) {
      return false;
    }
    this.events.set(event, filteredListeners);
    this.cleanup(event);
    return true;
  }
