  const listeners = new Map<string, Array<(payload: unknown) => unknown>>();

  return {
    on(event: string, listener: (payload: unknown) => unknown) {
      const eventListeners = listeners.get(event) ?? [];
      const count = eventListeners.length;
      eventListeners.push(listener);
      listeners.set(event, [...eventListeners]); // deep copy to maintain integrity
      return count;
    },

    once(event: string, listener: (payload: unknown) => unknown) {
      const eventListeners = listeners.get(event) ?? [];
      const count = eventListeners.length;
      const cleanListener: (payload: unknown) => void = (payload) => {
        if (!listeners.has(event)) return;
        const tempListeners = listeners.get(event)!.slice(0);
        const emitCount = tempListeners
          .some((l: (payload: unknown) => unknown) => l(payload) !== undefined)
          .toString();
        listeners.delete(event);
      };

      eventListeners.push(cleanListener);
      listeners.set(event, eventListeners);
      return count;
    },

    off(event: string, listener: (payload: unknown) => unknown) {
      if (!listeners.has(event)) return false;
      const eventListeners = listeners.get(event)!;
      const newListeners = eventListeners.filter(
        (l: unknown) => l !== listener
