export function createRateLimiter(): RateLimiter {
  const state: Map<string, { windowStart: number; count: number }> = new Map();

  return {
    allow: (key: string, nowMs: number): boolean => {
      const entry = state.get(key);
      if (!entry) {
        state.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (nowMs - entry.windowStart >= 1000) {
        entry.windowStart = nowMs;
        entry.count = 1;
        return true;
      }

      if (entry.count < 3) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      const entry = state.get(key);
      const quota = entry ? 3 - entry.count : 3;

      if (nowMs - entry.windowStart >= 1000) {
        return quota;
      }
      return Math.max(0, quota);
    },
    reset: (key: string): void => state.delete(key),
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
