export function createTtlCache() {
    const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
            const expiresAt = nowMs + (ttlMs ?? 1000);
            cache.delete(key);
            cache.set(key, { value, expiresAt });
        },
        get(key: string, nowMs: number): unknown {
            const entry = cache.get(key);
            if (!entry || nowMs >= entry.expiresAt) {
                cache.delete(key);
                return undefined;
            }
            return entry.value;
        },
        has(key: string, nowMs: number): boolean {
            return cache.has(key) && nowMs < cache.get(key)?.expiresAt ?? Infinity;
        },
        delete(key: string): boolean {
            return cache.delete(key);
        },
        size(_, nowMs: number): number {
            const nonExpiredEntries = Array.from(cache.entries())
                .filter(([, expiresAt]) => nowMs < expiresAt);
            return nonExpiredEntries.length;
        },
        clear(): void {
            cache.clear();
        },
    };
}
