export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const keys: Map<string, { allow: (key: string, nowMs: number) => boolean; remaining: (key: string, nowMs: number) => number; reset: (key: string) => void }> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!keys.has(key)) {
        keys.set(key, { allow: () => true, remaining: () => limit, reset: () => void 0 });
      }
      const { allow, remaining, reset } = keys.get(key)!;
      const windowStart = nowMs - windowMs;
      const used = remaining() - 1;
      if (used < 0) {
        return false;
      }
      if (nowMs - windowStart >= windowMs) {
        reset();
      }
      return allow();
    },
    remaining(key: string, nowMs: number): number {
      if (!keys.has(key)) {
        return 0;
      }
      const { allow, remaining } = keys.get(key)!;
      const windowStart = nowMs - windowMs;
      const used = remaining() - 1;
      if (used < 0) {
        return 0;
      }
      if (nowMs - windowStart >= windowMs) {
        return 0;
      }
      return used;
    },
    reset(key: string) {
      if (!keys.has(key)) {
        return;
      }
      const { allow, remaining } = keys.get(key)!;
      const windowStart = Date.now() - windowMs;
      const used = remaining() - 1;
      if (used < 0) {
        return;
      }
      if (Date.now() - windowStart >= windowMs) {
        keys.set(key, { allow: () => true, remaining: () => limit, reset: () => void 0 });
      }
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
