  const todos = [] as Array<{
    id: number;
    text: string;
    completed: boolean;
  }>;

  const addTodo = (text: string): { id: number, text: string, completed: boolean } => {
    const id = todos.length > 0 ? todos[todos.length - 1].id + 1 : 1;
    const todo = { id, text, completed: false };
    todos.push(todo);
    return todo;
  };

