    completed: boolean;
  }> => {
    return todos;
  };

  const listCompleted = (): Array<{
    id: number;
    text: string;
    completed: boolean;
  }> => {
    return todos.filter(t => t.completed);
  };

  const listPending = (): Array<{
    id: number;
    text: string;
    completed: boolean;
