export function createTtlCache(): TtlCache {
  const cache = {
    _entries: new Map<string, { value: string; expiresAt: number }>(),
    _nowMs: 0
  };

  // Default TTL is 1000ms
  cache._nowMs = Date.now();

  return {
    set(key: string, value: string, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs || 1000);
      cache._entries.set(key, {
        value,
        expiresAt
      });
      cache._nowMs = nowMs;
    },

    get(key: string, nowMs: number): string {
      const entry = cache._entries.get(key);
      if (!entry) return "";
      if (nowMs > entry.expiresAt) {
        delete cache._entries.get(key)!;
        return "";
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache._entries.get(key);
      if (!entry) return false;
      if (nowMs > entry.expiresAt) {
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      const entry = cache._entries.get(key);
      if (!entry) return false;
      delete cache._entries.get(key)!;
      return true;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of cache._entries.entries()) {
        if (nowMs > entry.expiresAt) continue;
        count++;
      }
      return count;
    },

    clear(): void {
      cache._entries.clear();
    }
  };
}

interface TtlCache {
  set(key: string, value: string, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): string;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
