export function createCalculator() {
  let currentValue = 0;
  let memory = 0;

  return {
    add(num: number): Calculator {
      currentValue += num;
      return this;
    },
    subtract(num: number): Calculator {
      currentValue -= num;
      return this;
    },
    multiply(num: number): Calculator {
      currentValue *= num;
      return this;
    },
    divide(num: number): Calculator {
      if (num === 0) throw new Error('Division by zero');
      currentValue /= num;
      return this;
    },
    clear(): Calculator {
      currentValue = 0;
      return this;
    },
    result(): number {
      return currentValue;
    },
    memoryStore(): Calculator {
      memory = currentValue;
      return this;
    },
    memoryAdd(): Calculator {
      memory += currentValue;
      return this;
    },
    memoryClear(): Calculator {
      memory = 0;
      return this;
    },
    memoryRecall(): { value: number; calculator: Calculator } {
      return { value: memory, calculator: this };
    }
  };
}

