class Calculator {
  private current: number = 0;
  private memory: number = 0;

  add(n: number): Calculator {
    this.current += n;
    return this;
  }

  subtract(n: number): Calculator {
    this.current -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this.current *= n;
    return this;
  }

  divide(n: number): Calculator {
    if (n !== 0) this.current /= n;
    return this;
  }

  clear(): Calculator {
    this.current = 0;
    return this;
  }

  result(): number {
    return this.current;
  }

  memoryStore(): Calculator {
    this.memory = this.current;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }

