export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { timestamps: number[]; windowStart: number }>();

  function allow(key: string, nowMs: number): boolean {
    let entry = state.get(key);
    if (!entry) {
      entry = { timestamps: [nowMs], windowStart: Math.floor(nowMs / windowMs) * windowMs };
      state.set(key, entry);
      return true;
    }

    const { timestamps, windowStart } = entry;

    if (nowMs - windowStart >= windowMs) {
      timestamps.length = 0;
      entry.windowStart = Math.floor(nowMs / windowMs) * windowMs;
    }

    if (timestamps.length < limit) {
      timestamps.push(nowMs);
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const entry = state.get(key);
    if (!entry) {
      return limit;
    }

    const { timestamps, windowStart } = entry;

    if (nowMs - windowStart >= windowMs) {
      timestamps.length = 0;
      entry.windowStart = Math.floor(nowMs / windowMs) * windowMs;
    }

    return Math.max(limit - timestamps.length, 0);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
