export function createEventEmitter<TEv extends string = string>() {
  type Listener = (...args: any[]) => any;
  const listenersMap = new Map<TEv, Array<{ fn: Listener; once: boolean }>>();

  function on(event: TEv, fn: Listener) {
    if (!listenersMap.has(event)) listenersMap.set(event, []);
    listenersMap.get(event)!.push({ fn, once: false });
  }

  function once(event: TEv, fn: Listener) {
    if (!listenersMap.has(event)) listenersMap.set(event, []);
    listenersMap.get(event)!.push({ fn, once: true });
  }

  function off(event: TEv, fn: Listener) {
    const list = listenersMap.get(event);
    if (!list) return;
    const idx = list.findIndex(l => l.fn === fn);
    if (idx !== -1) list.splice(idx, 1);
    if (list.length === 0) listenersMap.delete(event);
  }

  function emit(event: TEv, ...args: any[]) {
    const list = listenersMap.get(event);
    if (!list) return [];
    const results: any[] = [];
    // Make a copy to handle once removal during iteration
    const toInvoke = [...list];
    toInvoke.forEach(({ fn, once }) => {
      results.push(fn(...args));
      if (once) off(event, fn);
    });
    return results;
  }

  return { on, once, off, emit };
}

