export type Listener = (payload: unknown) => unknown

export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  type Subscriber = { fn: Listener; once: boolean }
  const events = new Map<string, Subscriber[]>()

  const add = (event: string, fn: Listener, once: boolean): number => {
    const subs = events.get(event) ?? []
    subs.push({ fn, once })
    events.set(event, subs)
    return subs.length
  }

  const remove = (event: string, fn: Listener): boolean => {
    const subs = events.get(event)
    if (!subs) return false
    const idx = subs.findIndex(sub => sub.fn === fn)
    if (idx === -1) return false
    subs.splice(idx, 1)
    if (subs.length === 0) events.delete(event)
    else events.set(event, subs)
    return true
  }

  const emitter: EventEmitter = {
    on(event, listener) {
      return add(event, listener, false)
    },
    once(event, listener) {
      return add(event, listener, true)
    },
    off(event, listener) {
      return remove(event, listener)
    },
    emit(event, payload) {
      const subs = events.get(event)
      if (!subs) return []
      const results: unknown[] = []
      // make a copy to allow modifications during iteration
      const subsCopy = [...subs]
      for (const sub of subsCopy) {
        results.push(sub.fn(payload))
        if (sub.once) remove(event, sub.fn)
      }
      return results
    },
    listenerCount(event) {
      const subs = events.get(event)
      return subs ? subs.length : 0
    }
  }

  return emitter
}
