export function createRateLimiter() {
  type KeyState = {
    windowStartMs: number;
    count: number;
  };

  const states = new Map<string, KeyState>();
  const WINDOW_MS = 1000;
  const MAX_REQUESTS = 3;

  return {
    request(key: string, nowMs: number): boolean {
      const state = states.get(key);

      if (!state) {
        states.set(key, { windowStartMs: nowMs, count: 1 });
        return true;
      }

      const elapsed = nowMs - state.windowStartMs;

      if (elapsed >= WINDOW_MS) {
        // Start new window
        state.windowStartMs = nowMs;
        state.count = 1;
        return true;
      }

      if (state.count < MAX_REQUESTS) {
        state.count += 1;
        return true;
      }

      return false;
    },

    reset(key: string): void {
      states.delete(key);
    }
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { windowStart: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    let entry = store.get(key);
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 };
      store.set(key, entry);
    }
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    if (entry.count < limit) {
      entry.count++;
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const entry = store.get(key);
    if (!entry) {
      return limit;
    }
    if (nowMs - entry.windowStart >= windowMs) {
      return limit;
    }
    return Math.max(limit - entry.count, 0);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return { allow, remaining, reset };
}

