export function createTodoApp() {
    type Todo = { id: number; text: string; completed: boolean };

    let nextId = 1;
    const todos = new Map<number, Todo>();

    return {
        addTodo(text: string): Todo {
            const todo: Todo = { id: nextId++, text, completed: false };
            todos.set(todo.id, todo);
            return todo;
        },
        getTodo(id: number): Todo | undefined {
            return todos.get(id);
        },
        toggleTodo(id: number): void {
            const todo = todos.get(id);
            if (todo) {
                todo.completed = !todo.completed;
            }
        },
        deleteTodo(id: number): boolean {
            return todos.delete(id);
        },
        listTodos(): Todo[] {
            return Array.from(todos.values());
        },
        listCompleted(): Todo[] {
            return Array.from(todos.values()).filter(t => t.completed);
        },
        listPending(): Todo[] {
            return Array.from(todos.values()).filter(t => !t.completed);
        },
        clearCompleted(): void {
            for (const [id, todo] of todos.entries()) {
                if (todo.completed) {
                    todos.delete(id);
                }
            }
        }
    };
}

export function createTodoApp(): TodoApp {
  interface Todo {
    id: number;
    text: string;
    completed: boolean;
  }

  interface TodoApp {
    addTodo(text: string): Todo;
    getTodo(id: number): Todo | undefined;
    toggleTodo(id: number): void;
    deleteTodo(id: number): boolean;
    listTodos(): Todo[];
    listCompleted(): Todo[];
    listPending(): Todo[];
    clearCompleted(): void;
  }

  let todos: Todo[] = [];
  let nextId = 1;

  return {
    addTodo(text: string): Todo {
      const todo: Todo = { id: nextId++, text, completed: false };
      todos.push(todo);
      return todo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(t => t.id === id);
    },

    toggleTodo(id: number): void {
      const todo = todos.find(t => t.id === id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(t => t.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter(t => t.completed);
    },

    listPending(): Todo[] {
      return todos.filter(t => !t.completed);
    },

    clearCompleted(): void {
      todos = todos.filter(t => !t.completed);
    }
  };
}

